import DOMPurify from 'dompurify';
import { marked } from 'marked';
import { ASSET_FOLDER } from './config';
import { contentUrl, type Change } from './github';

export interface Entry {
  /** Relative to the content root, no leading slash: "ideas/hello.md" */
  path: string;
  type: 'file' | 'folder';
  created: string;
  updated: string;
}

export interface Manifest {
  entries: Entry[];
}

/** Generated by blog-manifest.ts at build time (and on the fly in dev). */
export const MANIFEST = 'manifest.json';

/**
 * Dotfiles (.gitkeep, .DS_Store, …) are always hidden. The photo folder is
 * hidden from visitors (photos still render inside notes); authors see it.
 */
export const isHidden = (p: string, showAssets = false) =>
  p.split('/').some((seg) => seg.startsWith('.')) ||
  (!showAssets && p.split('/')[0].toLowerCase() === ASSET_FOLDER);

export type FileKind = 'note' | 'image' | 'other';

const IMAGE_EXT = /\.(png|jpe?g|gif|webp|svg|avif)$/i;

export function kindOf(path: string): FileKind {
  if (/\.(md|txt)$/i.test(path)) return 'note';
  if (IMAGE_EXT.test(path)) return 'image';
  return 'other';
}

export const isImage = (path: string) => IMAGE_EXT.test(path);
export const basename = (p: string) => p.slice(p.lastIndexOf('/') + 1);
export const dirname = (p: string) => (p.includes('/') ? p.slice(0, p.lastIndexOf('/')) : '');
export const join = (dir: string, name: string) => (dir ? `${dir}/${name}` : name);
/** "hello-world.md" → "hello-world" */
export const displayName = (p: string) => basename(p).replace(/\.(md|txt)$/i, '');

/** Strip characters that break URLs or git paths. Returns '' if nothing usable is left. */
export function cleanName(name: string): string {
  return name
    .trim()
    .replace(/[\\/:*?"<>|#%]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/^\.+/, '');
}

export function children(m: Manifest, dir: string, showAssets = false): Entry[] {
  return m.entries.filter((e) => dirname(e.path) === dir && !isHidden(e.path, showAssets));
}

/**
 * Index built from the repo's live file list (author mode), keeping the
 * git-derived dates from the deployed index where it has them.
 */
export function manifestFromFiles(files: string[], dated: Manifest | null): Manifest {
  const known = new Map((dated?.entries ?? []).map((e) => [e.path, e]));
  const now = new Date().toISOString();
  const entries = new Map<string, Entry>();
  for (const file of files) {
    if (file === MANIFEST) continue;
    const d = known.get(file);
    entries.set(file, { path: file, type: 'file', created: d?.created ?? now, updated: d?.updated ?? now });
    for (let dir = dirname(file); dir && !entries.has(dir); dir = dirname(dir)) {
      const k = known.get(dir);
      entries.set(dir, { path: dir, type: 'folder', created: k?.created ?? now, updated: k?.updated ?? now });
    }
  }
  return { entries: [...entries.values()] };
}

export function find(m: Manifest, path: string): Entry | undefined {
  return m.entries.find((e) => e.path === path);
}

export const exists = (m: Manifest, path: string) => path === '' || !!find(m, path);

/** Entry plus everything inside it (for folders). */
export function subtree(m: Manifest, path: string): Entry[] {
  return m.entries.filter((e) => e.path === path || e.path.startsWith(`${path}/`));
}

/** Pick "name.md", "name 2.md", … so nothing is ever overwritten. */
export function uniquePath(m: Manifest, dir: string, name: string): string {
  const dot = name.lastIndexOf('.');
  const stem = dot > 0 ? name.slice(0, dot) : name;
  const ext = dot > 0 ? name.slice(dot) : '';
  let candidate = join(dir, name);
  for (let i = 2; exists(m, candidate); i++) candidate = join(dir, `${stem} ${i}${ext}`);
  return candidate;
}

export function sortEntries(list: Entry[], by: 'name' | 'date'): Entry[] {
  return [...list].sort((a, b) => {
    if (a.type !== b.type) return a.type === 'folder' ? -1 : 1;
    if (by === 'date' && a.type === 'file') return b.updated.localeCompare(a.updated);
    return basename(a.path).localeCompare(basename(b.path), undefined, { numeric: true });
  });
}

/** Ensure every parent folder of `path` has an entry. */
export function withParents(m: Manifest, path: string, now: string): Entry[] {
  const added: Entry[] = [];
  let dir = dirname(path);
  while (dir && !exists(m, dir) && !added.some((e) => e.path === dir)) {
    added.push({ path: dir, type: 'folder', created: now, updated: now });
    dir = dirname(dir);
  }
  return added;
}

/** Changes + new manifest for moving `from` (file or folder) to `to`. */
export function planMove(m: Manifest, from: string, to: string): { changes: Change[]; next: Manifest } {
  const moved = subtree(m, from);
  const rename = (p: string) => to + p.slice(from.length);
  const changes: Change[] = [];
  for (const e of moved) {
    if (e.type !== 'file') continue;
    changes.push({ path: rename(e.path), copyFrom: e.path }, { path: e.path, delete: true });
  }
  const movedSet = new Set(moved.map((e) => e.path));
  const next: Manifest = {
    entries: m.entries.map((e) => (movedSet.has(e.path) ? { ...e, path: rename(e.path) } : e)),
  };
  return { changes, next };
}

// ---------- Markdown ----------

marked.setOptions({ gfm: true, breaks: true });

/** Resolve a link/image target written inside the note at `notePath`. */
export function resolvePath(target: string, notePath: string): string {
  if (target.startsWith('/')) return target.slice(1);
  const parts = dirname(notePath) ? dirname(notePath).split('/') : [];
  for (const seg of target.split('/')) {
    if (seg === '..') parts.pop();
    else if (seg && seg !== '.') parts.push(seg);
  }
  return parts.join('/');
}

const EXTERNAL = /^(https?:|mailto:|data:|blob:|#)/i;

/**
 * Markdown → sanitized HTML. Relative images point at the content store;
 * relative links to other notes become in-app #/ links.
 */
export function renderMarkdown(
  md: string,
  notePath: string,
  localImages: Map<string, string>,
  author = false,
): string {
  const html = DOMPurify.sanitize(marked.parse(md, { async: false }) as string);
  const doc = new DOMParser().parseFromString(`<div>${html}</div>`, 'text/html');
  doc.querySelectorAll('img').forEach((img) => {
    const src = img.getAttribute('src') ?? '';
    if (EXTERNAL.test(src)) return;
    const path = resolvePath(decodeURI(src), notePath);
    img.setAttribute('src', localImages.get(path) ?? contentUrl(path, author));
    img.setAttribute('loading', 'lazy');
  });
  doc.querySelectorAll('a').forEach((a) => {
    const href = a.getAttribute('href') ?? '';
    if (EXTERNAL.test(href)) {
      if (/^https?:/i.test(href)) {
        a.setAttribute('target', '_blank');
        a.setAttribute('rel', 'noopener noreferrer');
      }
      return;
    }
    a.setAttribute('href', `#/blog/${encodeURI(resolvePath(decodeURI(href), notePath))}`);
  });
  return doc.body.firstElementChild!.innerHTML;
}

export function readAsBase64(file: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(String(r.result).split(',')[1] ?? '');
    r.onerror = () => reject(r.error);
    r.readAsDataURL(file);
  });
}

export function formatDate(iso: string): string {
  if (!iso) return '';
  return new Date(iso).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}
